insert into public.feature_flags(key,enabled,config) values
 ('REGISTRATION_ENABLED',true,'{}'),('DISCOVERY_ENABLED',true,'{}'),('CHAT_ENABLED',true,'{}'),('REFERRAL_ENABLED',true,'{}'),('BOOST_ENABLED',true,'{}'),
 ('MEMBERSHIP_ENABLED',false,'{"requiresQualifiedUsers":100}'),('PAYMENTS_ENABLED',false,'{"requiresQualifiedUsers":100}'),('ADS_ENABLED',false,'{"requiresQualifiedUsers":100}'),('PAID_BOOST_ENABLED',false,'{"requiresQualifiedUsers":100}'),
 ('VIDEO_ENABLED',false,'{}'),('NEW_CITY_ENABLED',false,'{"launchCity":"Lima"}') on conflict(key) do nothing;

create table if not exists public.lima_district_settings(slug text primary key check(slug~'^[a-z0-9-]+$'),name text not null unique,status text not null default 'soft_open' check(status in('open','soft_open','closed')),minimum_active_profiles integer not null default 20 check(minimum_active_profiles between 1 and 10000),nearby_districts text[] not null default '{}',updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
alter table public.lima_district_settings enable row level security;
drop policy if exists lima_districts_public_read on public.lima_district_settings;
create policy lima_districts_public_read on public.lima_district_settings for select to anon,authenticated using(true);
insert into public.lima_district_settings(slug,name,nearby_districts) values
 ('miraflores','Miraflores',array['san-isidro','barranco','surquillo','surco']),('san-isidro','San Isidro',array['miraflores','lince','magdalena','jesus-maria']),('barranco','Barranco',array['miraflores','chorrillos','surco']),('surco','Santiago de Surco',array['miraflores','barranco','san-borja','la-molina']),('san-borja','San Borja',array['surco','surquillo','la-molina']),('la-molina','La Molina',array['surco','san-borja','ate']) on conflict(slug) do nothing;

create table if not exists public.referral_codes(user_id uuid primary key references auth.users(id) on delete cascade,code text not null unique check(code~'^[A-Z0-9]{6,16}$'),created_at timestamptz not null default now());
create table if not exists public.referrals(id bigint generated always as identity primary key,referrer_id uuid not null references auth.users(id) on delete cascade,referred_id uuid not null unique references auth.users(id) on delete cascade,code text not null,status text not null default 'registered' check(status in('registered','qualified','rejected')),qualified_at timestamptz,created_at timestamptz not null default now(),check(referrer_id<>referred_id));
create table if not exists public.boost_wallets(user_id uuid primary key references auth.users(id) on delete cascade,available_days integer not null default 0 check(available_days>=0),updated_at timestamptz not null default now());
create table if not exists public.boost_wallet_ledger(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,referral_id bigint references public.referrals(id) on delete set null,days_delta integer not null check(days_delta<>0),reason text not null,created_at timestamptz not null default now(),unique(referral_id,reason));
alter table public.referral_codes enable row level security;alter table public.referrals enable row level security;alter table public.boost_wallets enable row level security;alter table public.boost_wallet_ledger enable row level security;
create policy referral_codes_self_read on public.referral_codes for select to authenticated using(user_id=(select auth.uid()));
create policy referrals_party_read on public.referrals for select to authenticated using(referrer_id=(select auth.uid()) or referred_id=(select auth.uid()));
create policy boost_wallet_self_read on public.boost_wallets for select to authenticated using(user_id=(select auth.uid()));
create policy boost_ledger_self_read on public.boost_wallet_ledger for select to authenticated using(user_id=(select auth.uid()));

create or replace function public.admin_get_lima_launch_dashboard() returns jsonb language sql security definer stable set search_path=public,auth as $$with qualified as(select count(distinct p.id)::int n from public.profiles p join auth.users u on u.id=p.id join public.user_private priv on priv.user_id=p.id where p.country_code='PE' and lower(p.city)='lima' and p.profile_completion>=80 and p.status='active' and u.email_confirmed_at is not null and priv.birth_date<=current_date-interval '18 years' and exists(select 1 from public.profile_photos ph where ph.user_id=p.id and ph.status='approved')) select jsonb_build_object('qualifiedUsers',(select n from qualified),'target',100,'profiles',(select count(*) from public.profiles),'matches',(select count(*) from public.matches),'messages',(select count(*) from public.messages),'openReports',(select count(*) from public.reports where status in('open','triaged','investigating')),'generatedAt',now());$$;
revoke all on function public.admin_get_lima_launch_dashboard() from public,anon,authenticated;grant execute on function public.admin_get_lima_launch_dashboard() to service_role;

create or replace function public.qualify_lima_referrals() returns integer language plpgsql security definer set search_path=public,auth as $$declare r record;awarded integer:=0;begin for r in select x.id,x.referrer_id from public.referrals x join public.profiles p on p.id=x.referred_id join auth.users u on u.id=x.referred_id join public.user_private priv on priv.user_id=x.referred_id where x.status='registered' and p.country_code='PE' and lower(p.city)='lima' and p.profile_completion>=80 and p.status='active' and u.email_confirmed_at is not null and priv.birth_date<=current_date-interval '18 years' and exists(select 1 from public.profile_photos ph where ph.user_id=x.referred_id and ph.status='approved') loop update public.referrals set status='qualified',qualified_at=now() where id=r.id and status='registered';if found then insert into public.boost_wallets(user_id,available_days) values(r.referrer_id,1) on conflict(user_id) do update set available_days=public.boost_wallets.available_days+1,updated_at=now();insert into public.boost_wallet_ledger(user_id,referral_id,days_delta,reason) values(r.referrer_id,r.id,1,'qualified_referral');awarded:=awarded+1;end if;end loop;return awarded;end;$$;
revoke all on function public.qualify_lima_referrals() from public,anon,authenticated;grant execute on function public.qualify_lima_referrals() to service_role;
